import { useEffect, useRef } from 'react';
import './About.css';

export default function About() {
  const sectionRef = useRef(null);
  const cardRef = useRef(null);
  const canvasRef = useRef(null);

  /* reveal */
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { sectionRef.current?.classList.add('on'); obs.disconnect(); } },
      { threshold: 0.15 }
    );
    if (sectionRef.current) obs.observe(sectionRef.current);
    return () => obs.disconnect();
  }, []);

  /* elastic lanyard with canvas rope */
  useEffect(() => {
    const card = cardRef.current;
    const canvas = canvasRef.current;
    if (!card || !canvas) return;

    const ctx = canvas.getContext('2d');
    let x = 0, y = 0, vx = 0, vy = 0;
    let isDragging = false;
    let startX, startY;
    let raf;

    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const onDown = e => {
      isDragging = true;
      startX = e.clientX - x;
      startY = e.clientY - y;
      vx = 0; vy = 0;
      e.preventDefault();
    };
    const onMove = e => {
      if (!isDragging) return;
      x = e.clientX - startX;
      y = e.clientY - startY;
    };
    const onUp = () => { isDragging = false; };

    const animate = () => {
      if (!isDragging) {
        vx = vx * 0.88 - x * 0.08;
        vy = vy * 0.88 - y * 0.08 + 0.5;
        x += vx;
        y += vy;
      }

      // card move
      card.style.transform = `translate(${x}px, ${y}px) rotate(${x * 0.12}deg)`;
      card.style.transformOrigin = 'top center';

      // canvas rope draw
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // anchor point — top center of canvas
      const ax = canvas.width / 2;
      const ay = 0;

      // card top center
      const cr = card.getBoundingClientRect();
      const cvr = canvas.getBoundingClientRect();
      const cx = cr.left + cr.width / 2 - cvr.left;
      const cy = cr.top - cvr.top;

      // draw rope
      const grad = ctx.createLinearGradient(ax, ay, cx, cy);
      grad.addColorStop(0, 'rgba(0,247,255,0.9)');
      grad.addColorStop(1, 'rgba(0,247,255,0.3)');

      ctx.beginPath();
      ctx.moveTo(ax, ay);
      // bezier curve for natural sag
      ctx.bezierCurveTo(
        ax, ay + 60,
        cx, cy - 60,
        cx, cy
      );
      ctx.strokeStyle = grad;
      ctx.lineWidth = 2.5;
      ctx.lineCap = 'round';
      ctx.shadowColor = 'rgba(0,247,255,0.6)';
      ctx.shadowBlur = 8;
      ctx.stroke();

      // anchor dot
      ctx.beginPath();
      ctx.arc(ax, ay + 2, 5, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(0,247,255,0.8)';
      ctx.shadowBlur = 12;
      ctx.fill();

      raf = requestAnimationFrame(animate);
    };

    card.addEventListener('mousedown', onDown);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    raf = requestAnimationFrame(animate);

    return () => {
      card.removeEventListener('mousedown', onDown);
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <section id="about" className="section reveal" ref={sectionRef}>
      <div className="sec-label">01 — About</div>
      <h2 className="sec-title">Who I Am</h2>

      <div className="about-grid">

        <div className="iwrap">
          {/* canvas rope */}
          <canvas ref={canvasRef} className="rope-canvas" />
          {/* card — no HTML rope */}
          <div className="id-card" ref={cardRef} id="idCard">
            <div className="card-hole" />
            <div className="card-img">
              <img
                src="/images/my pic.jpeg"
                alt="M Ahmad"
                onError={e => e.target.style.display = 'none'}
              />
            </div>
            <div className="card-info">
              <span className="card-name">M Ahmad</span>
              <span className="card-role">Full Stack Dev</span>
              <div className="card-badge">
                <span className="card-dot" />
                Open to Work
              </div>
            </div>
          </div>
        </div>

        <div className="about-text">
          <p className="ahi">Junior Full Stack Developer</p>
          <p className="abio">
            Hey! I'm <strong>M Ahmad</strong> — a passionate <strong>Junior Full Stack Developer</strong> who
            recently stepped into web development. I may be a fresher, but I bring <strong>strong dedication,
              curiosity</strong>, and a genuine love for building things that work beautifully.
          </p>
          <p className="abio" style={{ marginTop: '16px' }}>
            On the <strong>frontend</strong>, I work with HTML, CSS, JavaScript, and React. I'm actively
            growing on the <strong>backend</strong> side — learning Node.js, Express &amp; MongoDB to become
            a complete developer.
          </p>
          <p className="abio" style={{ marginTop: '16px' }}>
            I believe every expert was once a beginner. I'm here to <strong>learn fast, build real
              things</strong>, and grow with every project. 🚀
          </p>
          <div className="about-tags">
            {['🎓 Fresh Graduate', '⚡ Fast Learner', '💡 Problem Solver', '🌐 Open to Work'].map(t => (
              <span key={t} className="atag">{t}</span>
            ))}
          </div>
        </div>

      </div>
    </section>
  );
}
